// @generated by:gauntlet run:godseye-local-recovery
import { randomUUID } from "node:crypto";
import { InfrastructureEngine } from "@godseye/core";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { RecoveryOverview } from "../packages/contracts/src/recovery.js";
import { recoveryCommitments } from "../packages/core/src/recovery-capacity.js";
import { fixtureProfile } from "./pg-helpers.js";
import { type RecoveryFixture, recoveryFixture, recoveryPolicy } from "./recovery-helpers.js";

describe("exact recovery source, fresh authority and atomic physical reservations", () => {
  let fixture: RecoveryFixture;
  beforeEach(async () => {
    fixture = await recoveryFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });

  it("T-AC-35 T-AC-39 exposes prepared-only scheduling and missing ancillary/effect coverage", async () => {
    const { backup } = await fixture.backup();
    expect(backup).toMatchObject({
      status: "archive-healthy",
      coverage: {
        filesAt: null,
        authAt: null,
        configAt: null,
        missing: ["files", "auth", "config", "effect-history", "producer-fencing"],
      },
    });
    expect(
      RecoveryOverview.parse(await fixture.infrastructure.recovery.overview(fixture.freshOwner())),
    ).toMatchObject({ activation: "blocked", schedule: "prepared-only" });
  });

  it("T-AC-35 marks stale archive evidence while preserving the already running source", async () => {
    const { backup } = await fixture.backup(),
      source = structuredClone(fixture.provider.resources.get(fixture.source.id));
    fixture.clock.advance((recoveryPolicy.maxArchiveAgeSeconds + 1) * 1000);
    const current = await fixture.infrastructure.recovery.overview(fixture.freshOwner());
    expect(current.backups.find((item) => item.id === backup.id)).toMatchObject({
      status: "stale",
      reason: "ARCHIVE_STALE",
    });
    expect(fixture.provider.resources.get(fixture.source.id)).toEqual(source);
  });

  it("T-AC-38 replays one exact backup preparation and rejects changed request identity", async () => {
    const first = await fixture.prepareBackup(),
      key = randomUUID();
    const input = {
      projectId: first.projectId,
      environmentId: first.sourceEnvironmentId,
      sourceAllocationId: first.sourceAllocationId,
      expectedProjectRevision: first.expectedProjectRevision,
      expectedEnvironmentRevision: first.expectedEnvironmentRevision,
      kind: "full" as const,
      policy: recoveryPolicy,
    };
    const saved = await fixture.infrastructure.recovery.prepareBackup(
      fixture.freshOwner(),
      input,
      key,
    );
    expect(
      await fixture.infrastructure.recovery.prepareBackup(fixture.freshOwner(), input, key),
    ).toEqual(saved);
    await expect(
      fixture.infrastructure.recovery.prepareBackup(
        fixture.freshOwner(),
        { ...input, kind: "diff" },
        key,
      ),
    ).rejects.toMatchObject({ code: "IDEMPOTENCY_CONFLICT" });
  });

  it.each(["environment", "project", "allocation"])(
    "T-AC-35 refuses a foreign source %s without physical effects",
    async (mode) => {
      const first = await fixture.prepareBackup();
      await expect(
        fixture.infrastructure.recovery.prepareBackup(
          fixture.freshOwner(),
          {
            projectId: mode === "project" ? fixture.secondProject.id : first.projectId,
            environmentId:
              mode === "environment" ? fixture.production.id : first.sourceEnvironmentId,
            sourceAllocationId: mode === "allocation" ? randomUUID() : first.sourceAllocationId,
            expectedProjectRevision: first.expectedProjectRevision,
            expectedEnvironmentRevision: first.expectedEnvironmentRevision,
            kind: "full",
            policy: recoveryPolicy,
          },
          randomUUID(),
        ),
      ).rejects.toMatchObject({ status: expect.any(Number) });
      expect(fixture.recoveryProvider.effects).toEqual([]);
    },
  );

  it.each(["service", "stale", "hash", "revision"])(
    "T-AC-38 refuses %s authority before reserving or dispatching",
    async (mode) => {
      const preparation = await fixture.prepareBackup();
      if (mode === "revision")
        await fixture.store.db
          .update(schema.projects)
          .set({ revision: fixture.project.revision + 1 })
          .where(eq(schema.projects.id, fixture.project.id));
      const actor =
        mode === "service"
          ? {
              id: "service-owner-claim",
              kind: "service" as const,
              projectIds: [fixture.project.id],
            }
          : mode === "stale"
            ? { ...fixture.freshOwner(), authenticatedAt: "2026-11-11T10:00:00.000Z" }
            : fixture.freshOwner();
      await expect(
        fixture.infrastructure.recovery.admit(
          actor,
          {
            preparationId: preparation.id,
            expectedHash: mode === "hash" ? "f".repeat(64) : preparation.hash,
          },
          randomUUID(),
        ),
      ).rejects.toBeDefined();
      expect((await fixture.infrastructure.recovery.overview(fixture.freshOwner())).runs).toEqual(
        [],
      );
      expect(fixture.recoveryProvider.effects).toEqual([]);
    },
  );

  it("T-AC-38 admits one durable run under concurrent duplicate requests and consumes one physical backup", async () => {
    const preparation = await fixture.prepareBackup(),
      key = randomUUID();
    const [a, b] = await Promise.all([
      fixture.admitRecovery(preparation, key),
      fixture.admitRecovery(preparation, key),
    ]);
    expect(a.id).toBe(b.id);
    await Promise.all([
      fixture.infrastructure.foundation.tick("recovery-worker-a"),
      fixture.infrastructure.foundation.tick("recovery-worker-b"),
    ]);
    expect(fixture.recoveryProvider.effects).toHaveLength(1);
    expect(
      (await fixture.infrastructure.recovery.overview(fixture.freshOwner())).runs,
    ).toHaveLength(1);
  });

  it("T-AC-38 rejects insufficient retained-source, repository, staging and WAL headroom atomically", async () => {
    const preparation = await fixture.prepareBackup("full", {
      ...recoveryPolicy,
      repositoryGiB: 16384,
    });
    await expect(fixture.admitRecovery(preparation)).rejects.toMatchObject({
      code: "CAPACITY_EXCEEDED",
    });
    expect((await fixture.infrastructure.recovery.overview(fixture.freshOwner())).runs).toEqual([]);
    expect(await recoveryCommitments(fixture.store.db)).toEqual([]);
    expect(fixture.provider.resources.get(fixture.source.id)?.running).toBe(true);
  });
  it("T-AC-35 prepares pure recovery policy without a qualified provider while denying execution", async () => {
    const preparation = await fixture.prepareBackup(),
      unconfigured = new InfrastructureEngine(fixture.store, {
        ...fixture.configuration,
        recoveryProvider: undefined,
      });
    const saved = await unconfigured.recovery.prepareBackup(
      fixture.freshOwner(),
      {
        projectId: preparation.projectId,
        environmentId: preparation.sourceEnvironmentId,
        sourceAllocationId: preparation.sourceAllocationId,
        expectedProjectRevision: preparation.expectedProjectRevision,
        expectedEnvironmentRevision: preparation.expectedEnvironmentRevision,
        kind: "full",
        policy: preparation.policy,
      },
      randomUUID(),
    );
    expect(saved.policy).toEqual(preparation.policy);
    await expect(
      unconfigured.recovery.admit(
        fixture.freshOwner(),
        { preparationId: saved.id, expectedHash: saved.hash },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "CAPABILITY_UNAVAILABLE" });
    expect((await unconfigured.recovery.overview(fixture.freshOwner())).runs).toEqual([]);
  });
  it.each(["scope", "generation", "stale", "future", "truthy-capacity"])(
    "T-AC-38 denies %s provider qualification without physical reservation",
    async (mode) => {
      const preparation = await fixture.prepareBackup();
      fixture.recoveryProvider.qualificationResult = (proof) => {
        if (mode === "scope") proof.scopeHash = "f".repeat(64);
        if (mode === "generation") proof.generation = "foreign-generation";
        if (mode === "stale") proof.expiresAt = "2026-11-11T11:59:59.000Z";
        if (mode === "future") proof.observedAt = "2026-11-11T12:00:01.000Z";
        if (mode === "truthy-capacity") Object.assign(proof, { capacityEnforced: "true" });
        return proof;
      };
      await expect(fixture.admitRecovery(preparation)).rejects.toMatchObject({
        code: "CAPABILITY_UNAVAILABLE",
      });
      expect(await recoveryCommitments(fixture.store.db)).toEqual([]);
      expect(fixture.recoveryProvider.effects).toEqual([]);
    },
  );
  it("T-AC-38 includes a retained restored allocation when admitting ordinary sibling databases", async () => {
    const { backup } = await fixture.backup();
    fixture.configuration.collector.observation.capacity.storageGiB = 25;
    await fixture.infrastructure.refreshInventory(
      fixture.freshOwner(),
      { expectedRevision: 1 },
      randomUUID(),
    );
    const preparation = await fixture.prepareRestore(backup.id);
    await fixture.admitRecovery(preparation);
    await fixture.infrastructure.foundation.tick("restore-retained-capacity-worker");
    await expect(fixture.admit(fixture.production.id)).rejects.toMatchObject({
      code: "CAPACITY_EXCEEDED",
    });
    expect(
      (await fixture.infrastructure.recovery.overview(fixture.freshOwner())).runs.find(
        (item) => item.preparationId === preparation.id,
      )?.state,
    ).toBe("restore-verified");
    expect(fixture.provider.resources.has(fixture.source.id)).toBe(true);
  });

  it("T-AC-38 denies a generic Foundation recovery plan without private exact admission", async () => {
    const preparation = await fixture.prepareBackup();
    const plan = await fixture.infrastructure.foundation.createPlan(
      fixture.freshOwner(),
      {
        projectId: preparation.projectId,
        environmentId: preparation.sourceEnvironmentId,
        targetId: preparation.id,
        expectedRevision: preparation.expectedProjectRevision,
        adapterId: "local.recovery",
        command: {
          kind: "database.recovery",
          intent: preparation.kind,
          manifestRef: preparation.id,
          manifestHash: preparation.hash,
        },
        maxCostMicros: 0,
        tools: ["recovery.full"],
        destinations: ["recovery.private"],
      },
      randomUUID(),
    );
    await fixture.infrastructure.foundation.approve(
      fixture.freshOwner(),
      plan.id,
      plan.hash,
      randomUUID(),
    );
    await expect(
      fixture.infrastructure.foundation.enqueue(fixture.freshOwner(), plan.id, randomUUID()),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
    expect((await fixture.infrastructure.recovery.overview(fixture.freshOwner())).runs).toEqual([]);
  });

  it("T-AC-37 creates a new held environment and allocation without bootstrapping or mutating source lineage", async () => {
    const { backup } = await fixture.backup(),
      source = structuredClone(fixture.provider.resources.get(fixture.source.id));
    const preparation = await fixture.prepareRestore(backup.id),
      run = await fixture.admitRecovery(preparation);
    await fixture.infrastructure.foundation.tick("held-clone-worker");
    const overview = await fixture.infrastructure.recovery.overview(fixture.freshOwner());
    expect(overview.runs.find((item) => item.id === run.id)).toMatchObject({
      state: "restore-verified",
      recoveryHold: true,
    });
    const project = await fixture.core.getProject(fixture.freshOwner(), fixture.project.id);
    expect(
      project.environments.find((item) => item.id === preparation.environmentId),
    ).toMatchObject({ kind: "recovery", recoveryHold: true });
    expect(preparation.environmentId).not.toBe(preparation.sourceEnvironmentId);
    expect(preparation.allocationId).not.toBe(preparation.sourceAllocationId);
    expect(
      fixture.recoveryProvider.resources.get(preparation.id)?.destination?.sourceSystemIdentifier,
    ).toBe(source?.systemIdentifier);
    expect(fixture.provider.resources.get(fixture.source.id)).toEqual(source);
    expect(fixture.provider.effects.map((effect) => effect.action)).toEqual(["provision"]);
  });

  it("T-AC-37 replays target preparation without creating extra environments and rejects reused names", async () => {
    const { backup } = await fixture.backup(),
      preparation = await fixture.prepareRestore(backup.id);
    const before = await fixture.core.getProject(fixture.freshOwner(), fixture.project.id);
    await expect(fixture.prepareRestore(backup.id)).rejects.toMatchObject({
      code: "ENVIRONMENT_LIMIT",
    });
    const after = await fixture.core.getProject(fixture.freshOwner(), fixture.project.id);
    expect(after.environments).toEqual(before.environments);
    expect(after.environments.filter((item) => item.id === preparation.environmentId)).toHaveLength(
      1,
    );
  });

  it("T-AC-40 keeps activation blocked despite verified database recovery and a fresh owner epoch", async () => {
    const { backup } = await fixture.backup(),
      preparation = await fixture.prepareRestore(backup.id);
    await fixture.admitRecovery(preparation);
    await fixture.infrastructure.foundation.tick("activation-assessment-worker");
    await fixture.infrastructure.foundation.advanceEpoch(
      fixture.freshOwner(),
      fixture.development.id,
      randomUUID(),
    );
    const assessment = await fixture.infrastructure.recovery.assessActivation(
      fixture.freshOwner(),
      preparation.environmentId,
    );
    expect(assessment).toMatchObject({ recoveryHold: true, activation: "blocked" });
    expect(assessment.reasons).toEqual(
      expect.arrayContaining([
        "PRODUCER_FENCING_UNQUALIFIED",
        "NON_REWOUND_BUSINESS_EFFECT_COVERAGE_UNQUALIFIED",
        "FILES_SNAPSHOT_MISSING",
        "AUTH_SNAPSHOT_MISSING",
        "CONFIG_SNAPSHOT_MISSING",
      ]),
    );
  });

  it("T-AC-40 blocks ordinary database preparation and generic task plans in the held destination", async () => {
    const { backup } = await fixture.backup(),
      preparation = await fixture.prepareRestore(backup.id);
    const project = await fixture.core.getProject(fixture.freshOwner(), fixture.project.id);
    const env = project.environments.find((item) => item.id === preparation.environmentId);
    if (!env) throw new Error("Held recovery destination missing");
    await expect(
      fixture.infrastructure.database.prepare(
        fixture.freshOwner(),
        {
          projectId: project.id,
          environmentId: env.id,
          expectedProjectRevision: project.revision,
          expectedEnvironmentRevision: env.revision,
          profile: fixtureProfile,
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "RECOVERY_HOLD" });
    await expect(
      fixture.infrastructure.foundation.createPlan(
        fixture.freshOwner(),
        {
          projectId: project.id,
          environmentId: env.id,
          targetId: preparation.id,
          expectedRevision: project.revision,
          adapterId: "local.recovery",
          command: {
            kind: "database.recovery",
            intent: "restore",
            manifestRef: preparation.id,
            manifestHash: preparation.hash,
          },
          maxCostMicros: 0,
          tools: ["recovery.restore"],
          destinations: ["recovery.private"],
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "RECOVERY_HOLD" });
  });
});
